{"content": """"convert.convert 的单元测试（标准库 unittest）。

运行方式：
    python3 -m unittest -v test_convert -v
或：
    python3 -m unittest discover -v
"""

import unittest
from decimal import Decimal

from convert import convert


class TestConvertHappyPath(unittest.TestCase):
    """需求中明确列出的四个换算用例。"""

    def test_1_25_kg_to_g(self):
        self.assertEqual(convert(1.25, "kg", "g"), "1250")

    def test_0_1_g_to_mg(self):
        self.assertEqual(convert(0.1, "g", "mg"), "100")

    def test_1234_mg_to_g(self):
        self.assertEqual(convert(1234, "mg", "g"), "1.234")

    def test_0_g_to_mg(self):
        self.assertEqual(convert(0, "g", "mg"), "0")


class TestConvertSameUnitAndScale(unittest.TestCase):
    def test_identity_kg(self):
        self.assertEqual(convert(3, "kg", "kg"), "3")

    def test_kg_to_mg(self):
        self.assertEqual(convert(1, "kg", "mg"), "1000000")

    def test_mg_to_kg(self):
        self.assertEqual(convert(1000000, "mg", "kg"), "1")

    def test_g_to_kg(self):
        self.assertEqual(convert(2500, "g", "kg"), "2.5")

    def test_decimal_precision_is_exact(self):
        # float 版本会得到 99.99999999999999，Decimal 必须给出 100。
        self.assertEqual(convert(0.1, "g", "mg"), "100")
        self.assertEqual(convert(0.3, "g", "mg"), "300")

    def test_input_forms_agree(self):
        for value in (1.25, "1.25", Decimal("1.25")):
            with self.subTest(value=value):
                self.assertEqual(convert(value, "kg", "g"), "1250")

    def test_string_input_high_precision(self):
        self.assertEqual(convert("0.000001", "kg", "mg"), "1")
        self.assertEqual(convert("1e-6", "kg", "mg"), "1")

    def test_returns_str(self):
        self.assertIsInstance(convert(1, "kg", "g"), str)


class TestTrailingZeroFormatting(unittest.TestCase):
    def test_no_trailing_zeros(self):
        self.assertEqual(convert(1.500, "kg", "g"), "1500")
        self.assertEqual(convert("2.000", "kg", "kg"), "2")

    def test_zero_variants_collapse_to_zero(self):
        for value in (0, "0", "0.000", Decimal("0.0")):
            with self.subTest(value=value):
                self.assertEqual(convert(value, "kg", "mg"), "0")

    def test_fraction_kept(self):
        self.assertEqual(convert(1, "mg", "g"), "0.001")


class TestNegativeRejection(unittest.TestCase):
    def test_negative_int(self):
        with self.assertRaises(ValueError):
            convert(-1, "kg", "g")

    def test_negative_float(self):
        with self.assertRaises(ValueError):
            convert(-0.5, "g", "mg")

    def test_negative_string(self):
        with self.assertRaises(ValueError):
            convert("-3", "mg", "g")

    def test_negative_decimal(self):
        with self.assertRaises(ValueError):
            convert(Decimal("-1.5"), "kg", "mg")

    def test_negative_is_rejected_even_for_valid_units(self):
        with self.assertRaises(ValueError) as ctx:
            convert(-10, "kg", "kg")
        self.assertIn("负", str(ctx.exception))


class TestUnitRejection(unittest.TestCase):
    def test_unknown_from_unit(self):
        with self.assertRaises(ValueError):
            convert(1, "lb", "g")

    def test_unknown_to_unit(self):
        with self.assertRaises(ValueError):
            convert(1, "kg", "tonne")

    def test_case_sensitive(self):
        for bad in ("KG", "G", "Mg"):
            with self.subTest(unit=bad):
                with self.assertRaises(ValueError):
                    convert(1, bad, "g")

    def test_empty_and_whitespace_padded(self):
        with self.assertRaises(ValueError):
            convert(1, "", "g")
        # 前后空白被容忍，内部名称本身仍然合法。
        self.assertEqual(convert(1, " kg ", " g "), "1000")

    def test_non_string_unit(self):
        for bad in (None, 1, b"kg"):
            with self.subTest(unit=bad):
                with self.assertRaises(ValueError):
                    convert(1, bad, "g")


class TestBadValueRejection(unittest.TestCase):
    def test_unparsable_string(self):
        for bad in ("abc", "1.2.3", "", "  "):
            with self.subTest(value=bad):
                with self.assertRaises(ValueError):
                    convert(bad, "kg", "g")

    def test_bool_rejected(self):
        with self.assertRaises(ValueError):
            convert(True, "kg", "g")

    def test_non_finite(self):
        for bad in (float("nan"), float("inf"), "-inf"):
            with self.subTest(value=bad):
                with self.assertRaises(ValueError):
                    convert(bad, "kg", "g")

    def test_unsupported_type(self):
        for bad in (None, [1], {"v": 1}, object()):
            with self.subTest(value=bad):
                with self.assertRaises(ValueError):
                    convert(bad, "kg", "g")


if __name__ == "__main__":
    unittest.main(verbosity=2)
